<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Bursar'],true)){http_response_code(403);exit('Access denied.');}
$year=filter_var($_GET['year']??date('Y'),FILTER_VALIDATE_INT);if(!$year||$year<2000||$year>2100){http_response_code(400);exit('Choose a valid year.');}
$statuses=['Submitted','Approved','Rejected','Paid'];$categories=['Utilities','Repairs and maintenance','Learning materials','Transport','Food and boarding','Examinations','Administration','Communication','Security','Other'];
$status=(string)($_GET['status']??'');$category=(string)($_GET['category']??'');if($status!==''&&!in_array($status,$statuses,true)){http_response_code(400);exit('Choose a valid status.');}if($category!==''&&!in_array($category,$categories,true)){http_response_code(400);exit('Choose a valid category.');}
$where=['e.expense_date BETWEEN :start AND :end'];$params=['start'=>$year.'-01-01','end'=>$year.'-12-31'];if($status!==''){$where[]='e.status=:status';$params['status']=$status;}if($category!==''){$where[]='e.category=:category';$params['category']=$category;}
$stmt=db()->prepare('SELECT e.expense_date,e.category,e.supplier,e.description,e.invoice_reference,e.amount,e.currency,e.status,creator.full_name AS creator_name,e.created_at,reviewer.full_name AS reviewer_name,e.reviewed_at,e.review_note,payer.full_name AS payer_name,e.paid_at,e.payment_method,e.payment_reference FROM school_expenses e LEFT JOIN users creator ON creator.id=e.created_by LEFT JOIN users reviewer ON reviewer.id=e.reviewed_by LEFT JOIN users payer ON payer.id=e.paid_by WHERE '.implode(' AND ',$where).' ORDER BY e.expense_date,e.id');$stmt->execute($params);
$safe=static function(mixed $value): string{$value=(string)$value;return preg_match('/^[\s]*[=+@-]/u',$value)?"'".$value:$value;};
header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="mavambo-expenses-'.$year.'.csv"');header('X-Content-Type-Options: nosniff');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Expense date','Category','Supplier / payee','Description','Invoice / voucher reference','Amount','Currency','Status','Submitted by','Submitted at','Reviewed by','Reviewed at','Review note','Paid by','Paid at','Payment method','Payment reference']);while($row=$stmt->fetch(PDO::FETCH_NUM)){foreach($row as &$value)if(is_string($value))$value=$safe($value);unset($value);fputcsv($out,$row);}fclose($out);exit;
